 const runScenario=(key:string,title:string)=>setModal({title:'Run scenario '+key+' · '+title,description:key==='E'?'Create 100 confirmed synthetic orders and compute an allocation proposal. Shipment booking requires a separate approval in Allocation Studio.':key==='G'?'Generate three delivered shipments and missing, mismatched and matched remittances. These synthetic outcomes are preapproved for this scenario.':key==='H'?'Preapprove intake, confirmation, courier booking, a reproducible delivered or returned outcome, and synthetic reconciliation.':key==='I'?'Create and confirm an order, then book an eligible alternative courier with an audited manager override.':`Execute this synthetic workflow with seed ${demoSeed}. All decisions are persisted and use the operational APIs’ business services.`,approval:true,submit:'Run synthetic scenario',onSubmit:async()=>{const r=await api('/demo/scenarios/'+key+'/run','POST',{approved:true,seed:demoSeed,response:scenarioResponse});setScenarioResult(r);if(r.proposal)setProposal(r.proposal);refresh();notify('Scenario '+key+' completed');}});
 const editRate=(q:Item)=>setModal({title:'Edit '+q.code+' rate card',description:'All rates are fictional. Missing reverse fees exclude a carrier from modeled optimization. Changes invalidate existing proposals.',fields:[{key:'capacity',label:'Daily capacity · shipments',type:'number',value:q.capacity,min:0,max:1000,required:true},{key:'forward_pkr',label:'Base forward fee · PKR',type:'number',value:q.forward/100,min:0,step:.01,required:true},{key:'reverse_pkr',label:'Return fee · PKR (blank = unknown)',type:'number',value:q.reverse===null?'':q.reverse/100,min:0,step:.01},{key:'cod_fee_pkr',label:'COD fee · PKR',type:'number',value:q.cod_fee/100,min:0,step:.01,required:true},{key:'active',label:'Merchant-approved active carrier',type:'checkbox',value:!!q.active}],onSubmit:async d=>{await api('/couriers/'+q.id,'PUT',{capacity:d.capacity,forward:Math.round(d.forward_pkr*100),reverse:d.reverse_pkr===''?null:Math.round(d.reverse_pkr*100),cod_fee:Math.round(d.cod_fee_pkr*100),active:d.active});refresh();notify('Courier rate card updated');}});
